i=0
NIGHT='#20243a'
def nightsky(w=560,h=190): return f'<rect width="{w}" height="{h}" fill="{NIGHT}"/>'+''.join(f'<circle cx="{(37*k)%w}" cy="{(23*k*k)%(h-60)+8}" r="1.5" fill="#fff8d0" stroke="none"/>' for k in range(1,22))
def lamps_row(n,x0,dx,y,s=1.2): return ''.join(g(x0+k*dx,y,s,lamp()) for k in range(n))
def umbrella(): return '<path d="M0 0 v-40" stroke-width="2.5"/><path d="M-22 -36 q22 -24 44 0z" fill="#e0a800"/>'
def vamana(): return g(0,0,.75,person('#e0a800'))+g(14,-30,.8,umbrella())
def bali(c='#7a3fa0'): return god(c)+'<path d="M-10 -47 l2 -12 l4 6 l4 -9 l4 9 l4 -6 l2 12z" fill="#e0a800"/>'
def yama(): return god('#2a3a5a')
def lakshmi(): return devi(sari='#c0392b',items=('lotus','lotus'))
def krishna(): return god('#2a5aa8')
def garuda(): return g(0,0,1.6,bird('#c0582a'))
def big_step(): return '<path d="M0 0 q-4 -60 30 -120" fill="none" stroke="#2a5aa8" stroke-width="14"/><ellipse cx="34" cy="-124" rx="18" ry="9" fill="#2a5aa8"/>'
def lantern(c='#e0a800'): return f'<path d="M0 -40 v8"/><path d="M0 -32 l16 16 l-16 30 l-16 -30z" fill="{c}"/><path d="M-6 14 l-2 14 M0 14 v16 M6 14 l2 14" stroke="#c0392b"/>'
def rangoli(): return ''.join(f'<circle r="{r}" fill="none" stroke="{c}" stroke-width="4"/>' for r,c in [(36,'#c0392b'),(26,'#e0a800'),(16,'#2a9d6f'),(6,'#7a3fa0')])+''.join(f'<circle cx="{40*__import__("math").cos(k*0.785):.1f}" cy="{40*__import__("math").sin(k*0.785):.1f}" r="5" fill="#fff" stroke="#c0392b"/>' for k in range(8))
def pot_deco(): return pot('#c98a5a')+'<path d="M-14 -14 h28" stroke="#fff" stroke-width="3" stroke-dasharray="3 3"/><circle cy="-6" r="3" fill="#c0392b"/>'
def apamarga(): return '<path d="M0 0 v-46" stroke="#2f7a3a" stroke-width="2.5"/>'+''.join(f'<path d="M0 -{8+k*9} l{(-1)**k*12} -6" stroke="#2f7a3a" stroke-width="2"/>' for k in range(5))
def coins(): return ''.join(f'<ellipse cx="{x}" cy="{y}" rx="10" ry="4" fill="#e0a800"/>' for x,y in [(-12,0),(8,0),(-2,-6),(14,-8),(-8,-12)])
def ledger(): return '<rect x="-20" y="-26" width="40" height="30" rx="3" fill="#c0392b"/><path d="M-12 -18 h24 M-12 -10 h24" stroke="#e0a800" stroke-width="2"/><text x="0" y="-2" font-size="9" text-anchor="middle" fill="#fff" stroke="none" font-family="Noto Sans">śubha</text>'
def balifig(): return '<path d="M-26 0 l26 -52 l26 52z" fill="#6a5a3a"/><circle cy="-30" r="5" fill="#ffd60a"/>'+''.join(g(x,-6,.4,lotus('#ff8c1a','#e0a800')) for x in (-14,0,14))
L=lambda u,t: f'<a href="{u}">{t}</a>'
COV=covart('A row of clay lamps on a doorstep at night, a star-shaped sky lantern above, a rangoli at the threshold, and fireworks in the sky',nightsky(440,196)+g(70,60,1.2,lantern())+g(370,70,1.1,lantern('#c0392b'))+g(220,150,.9,rangoli())+lamps_row(7,40,60,192,1.5)+''.join(f'<path d="M{x} {y} l{dx} {dy}" stroke="#ffd60a" stroke-width="2"/>' for x,y,dx,dy in [(220,40,0,-14),(220,40,12,-8),(220,40,-12,-8),(220,40,12,8),(220,40,-12,8),(220,40,0,14)]))
pp=[foreword(i,['Dīpāvali is the one festival the whole of India keeps, and no two regions keep it alike. Karnataka fills water pots, bathes before dawn and welcomes King Bali home; Tamil Nadu asks “have you had your Gaṅgā bath?”; the north lights Ayodhyā for Rāma; Bengal worships Kālī; Gujarat begins its new year. Underneath all of it is one picture: <b>a lamp lit on the darkest night of the year</b>.','This article takes the festival day by day, from the thirteenth of the dark fortnight to the second of the bright one. It tells every story attached to it in full (Dhanvantari, the prince saved from Yama, Naraka, Lakṣmī, Bali and Vāmana, Yama and Yamunā, Rāma’s return), gives the verses said on each day from the Purāṇas, and explains how Karnataka keeps it.','Our main source is the <b>Skanda Purāṇa’s Kārttika-māhātmya</b>, whose ninth chapter is a complete Dīpāvali manual, with the Padma Purāṇa and the Bhāgavata for the stories.'],[('z','Five days? I thought Dīpāvali was one night.'),('b','The lamps are one night, Zappy. The festival is five days, and each day has its own story. Let’s take them one at a time.')]),
 glance([('Name','Dīpāvali, “row of lamps” (dīpa + āvali); Dīpāvaḷi in Kannada; also Dīpamālikā, Dīpotsava'),('When','Kṛṣṇa Trayodaśī to Śukla Dvitīyā, around the new moon of Āśvina/Kārtika (October–November); months named differently in amānta and pūrṇimānta calendars'),('Day 1','Dhana Trayodaśī: Dhanvantari, the Yama-dīpa; in Karnataka nīru tumbuva habba'),('Day 2','Naraka Caturdaśī: Kṛṣṇa slays Naraka; the dawn oil bath'),('Day 3','Amāvāsyā: Lakṣmī Pūjā; Kālī Pūjā in Bengal; Kedāra Gaurī in Karnataka'),('Day 4','Bali Pratipadā (Bali Pāḍyami): Bali’s yearly return; gō-pūjā; Govardhana pūjā'),('Day 5','Yama Dvitīyā: Yama dines with his sister Yamunā; Bhāī Dūj'),('Main text','Skanda Purāṇa, Vaiṣṇava Khaṇḍa, Kārttika-māhātmya ch. 9; Padma Purāṇa, Uttara Khaṇḍa')],svg(560,150,'Five lamps for the five days, labelled with their names',nightsky(560,150)+''.join(g(70+k*105,95,1.8,lamp())+lab(70+k*105,130,t).replace('fill="#111"','fill="#fff8d0"') for k,t in enumerate(['Trayodaśī','Caturdaśī','Amāvāsyā','Pratipadā','Dvitīyā'])))),
 reading('name','THE NAME AND THE NIGHT','Why lamps on the new moon',svg(560,170,'The waning moon shrinking to the dark new moon, with a row of lamps lit beneath it',nightsky(560,170)+''.join(f'<circle cx="{60+k*90}" cy="50" r="18" fill="#fff8d0" stroke="#111"/><circle cx="{60+k*90+k*7}" cy="50" r="18" fill="{NIGHT}" stroke="none"/>' for k in range(6))+lamps_row(8,50,65,150,1.4)),['<b>The word.</b> <i>Dīpa</i> is a lamp and <i>āvali</i> a row or line: Dīpāvali is a row of lamps. Old texts also call it <b>Dīpamālikā</b> (a garland of lamps) and <b>Dīpotsava</b> (the lamp festival); Kannada says Dīpāvaḷi, and many Karnataka villages simply call it <b>doḍḍa habba</b>, the big festival.','<b>The darkest night.</b> The centre of the festival is <b>Amāvāsyā</b>, the new moon of the month that ends the rains. There is no moonlight at all; the lamps carry the whole night. Many teachers read this as the festival’s lesson: light matters most where it is darkest. (Interpretation.)','<b>Which month?</b> In the amānta calendar used in Karnataka, the new moon ends Āśvina and the next day begins Kārtika; in the pūrṇimānta calendar of the north the same night falls in Kārtika. It is one night with two month-names, and the reason sources seem to disagree.','<b>The start of Kārtika.</b> In Karnataka the festival opens the '+L('/festivals/kartika/','month of Kārtika')+', the month of lamps, and in many homes the lamps simply continue every evening until Kārtika Pūrṇimā.'],[('z','So the new moon is the main day?'),('b','For Lakṣmī, yes. But in Karnataka and Tamil Nadu the dawn bath the day before often feels like the real Dīpāvali. That’s why the five days matter.')],'A row of lamps on <b>the moonless night</b>.'),
 reading('history','A FESTIVAL OVER A THOUSAND YEARS OLD','What the old records say',svg(560,150,'A timeline from the seventh century to the sixteenth with a lamp on each mark',ground(560,150,100,'#e3eaf3')+'<path d="M30 80 h500" stroke-width="3"/>'+''.join(g(x,74,1,lamp())+lab(x,100,t)+lab(x,116,s) for x,t,s in [(60,'7th c.','Nāgānanda'),(170,'9th c.','Kāvyamīmāṃsā'),(280,'10th c.','Kannada plates'),(390,'11th c.','al-Bīrūnī'),(500,'16th c.','Vijayanagara')])),['<b>The plays and poets.</b> Harṣa’s seventh-century drama <i>Nāgānanda</i> names a <b>Dīpapratipadutsava</b>, a lamp festival on the first day of the bright fortnight, when newly-weds received gifts. In the ninth century Rājaśekhara’s <i>Kāvyamīmāṃsā</i> calls it <b>Dīpamālikā</b>, when houses were whitewashed and lit with lamps.','<b>Karnataka’s inscriptions.</b> Some of the oldest dated mentions come from Kannada country: a copper plate of the Rāṣṭrakūṭa king Kṛṣṇa III (tenth century) mentions a Dīpotsava, a tenth-century Jain inscription at Saundatti and a twelfth-century inscription at Dharwad record lamp festivals. (Details as summarised in secondary sources; we have not read the inscriptions themselves.)','<b>The travellers.</b> The Persian scholar al-Bīrūnī (eleventh century) described the festival on the new moon of Kārtika; the Italian Niccolò de’ Conti (fifteenth century) saw lamps burning in temples; the Portuguese Domingo Paes described it at Vijayanagara in the sixteenth.','<b>The Purāṇas.</b> The Padma and Skanda Purāṇas give the fullest ritual accounts, day by day. Their dates are uncertain; scholars place much of this material between the seventh and tenth centuries.'],[('z','So it was already old when Vijayanagara was new?'),('b','Older than most of the temples you know, Zappy. And Karnataka’s stones are among its earliest witnesses.')],'Recorded for <b>over a thousand years</b>.'),
 story('dhanvantari','DAY 1 · DHANVANTARI','Dhana Trayodaśī: the healer rises from the ocean',strip('Three panels: gods and demons churning the ocean; Dhanvantari rising with a pot of nectar; demons snatching the pot',[panel([(god(),0.77),(mountain('#8a7a5a',False),0.98),(demon(),0.77)],'#dfe9f6',150),panel([(river(144,130),1),(god('#e0a800'),.8),(pot('#e0a800'),0.98)],'#dfe9f6',None),panel([(demon(),0.84),(pot('#e0a800'),0.98),(demon('#6a2a2a'),0.84)],'#fde4e4',150)],['the ocean churned','Dhanvantari appears','the nectar seized']),'The first day honours the physician of the gods. The story is in the Bhāgavata Purāṇa, book 8.',['Gods and demons churned the ocean of milk with Mount Mandara and the serpent Vāsuki, seeking <b>amṛta</b>, the nectar of immortality. (The whole churning is told in our '+L('/festivals/pradosha/nilakantha/','Nīlakaṇṭha article')+'.)','First the poison rose, which Śiva drank; then came treasures: the wish-cow, the white horse, the elephant Airāvata, the Kaustubha gem, and Lakṣmī herself.','Last of all rose a dark, handsome youth with a pot full of nectar in his hands: <b>Dhanvantari</b>, master of Āyurveda, a portion of Viṣṇu.','The demons snatched the pot from his hands, and Viṣṇu had to take the form of Mohinī to win it back for the gods.','Because the healer appeared with the nectar of life, Trayodaśī is kept by many as <b>Dhanvantari Jayantī</b>, and India now marks it as National Ayurveda Day.'],[('z','Is “Dhanteras” about money or medicine?'),('b','Both, and the words are mixed up. <i>Dhana</i> is wealth; Dhanvantari is the healer. Health is the first wealth, so many families honour him before Lakṣmī.')],'The healer comes <b>with the nectar of life</b>.'),
 verse('v-dhanvantari','Bhāgavata 8.8.34','Dhanvantari, the portion of Viṣṇu',['sa vai bhagavataḥ sākṣād viṣṇor aṃśāṃśa-sambhavaḥ','dhanvantarir iti khyāta āyur-veda-dṛg ijya-bhāk'],svg(200,150,'Dhanvantari holding a pot of nectar',ground(200,150,120,'#dfe9f6')+g(100,135,1.1,god('#2a5aa8'))+g(130,100,.6,pot('#e0a800'))),'He was born directly from a portion of a portion of the Lord Viṣṇu. He became famous as Dhanvantari: the seer of the science of life, and one entitled to a share in the sacrifices.',[('aṃśāṃśa-sambhavaḥ','born of a portion of a portion'),('khyātaḥ','renowned'),('āyur-veda','the knowledge of life, medicine'),('dṛk','seer, master'),('ijya-bhāk','sharer in the sacrificial offerings')],'<b>Why it matters on Day 1.</b> The verse gives Dhanvantari a place among the gods who receive offerings, which is why Āyurveda physicians hold a havan to him on Trayodaśī and many homes say his name before buying a new vessel. The <b>new pot or metal vessel</b> bought this day links the two meanings of <i>dhana</i>: the pot of nectar and household wealth. (The link is popular tradition, not in the verse.)',k='<b>Health first</b>, then wealth.',note='Text: Bhāgavata Purāṇa 8.8.34, as in the BBT edition (vedabase / prabhupadabooks.com), set in IAST.'),
 story('hima','THE PRINCE SAVED FROM YAMA','The story of the Yama-dīpa',strip('Three panels: an astrologer warning a king about his son; the bride surrounding the bedroom door with lamps and gold; Yama as a serpent dazzled and turning back',[panel([(sage('#ff8c1a'),0.98),(god('#7a3fa0'),0.98)],'#fff3cf',150),panel([(coins(),1.2),(lamp(),1.2),(lamp(),1.2)],'#2a2a3a',150),panel([('<path d="M-40 0 q20 -20 40 0 q20 20 40 0" fill="none" stroke="#2a6a3a" stroke-width="7"/>',1),(lamp(),1.2)],'#20243a',150)],['the prophecy','a wall of light','Yama turns back']),'The Skanda Purāṇa only names “the story of Hemanaka’s son”; this is the telling heard in most homes.',['King <b>Hima</b> (Hemanaka) had one son. Astrologers foretold that the prince would die of a snake-bite on the fourth night after his wedding.','The prince married, and his young bride heard the prophecy. On the fourth night she would not let him sleep.','She heaped all her gold and jewels at the door of the room, lit lamps all round them, and kept him awake telling stories and singing.','At midnight Yama came as a serpent. The blaze of lamps and gold dazzled him; he coiled on the heap, listened to her songs till dawn, and went away without his prize.','So on Trayodaśī evening a lamp is set out at the door, facing south, the direction of Yama: the <b>Yama-dīpa</b>, offered against untimely death.'],[('z','She beat Yama with lamps and songs?'),('b','With wakefulness, Zappy. The story says: stay awake, keep the light burning, and even death waits. That’s the Yama-dīpa.')],'A lamp at the door <b>against untimely death</b>.'),
 verse('v-yamadipa','The Yama-dīpa verse','Said while setting the lamp outside, facing south',['mṛtyunā pāśadaṇḍābhyāṃ kālena śyāmayā saha','trayodaśyāṃ dīpadānāt sūryajaḥ prīyatāṃ mama'],svg(200,150,'A lamp at a doorway facing south, with a dark figure of Yama far away',nightsky(200,150)+'<rect x="20" y="30" width="60" height="110" fill="#c98a5a"/><rect x="34" y="50" width="32" height="90" fill="#5a3a2a"/>'+g(110,132,1.6,lamp())+g(170,140,.45,yama())),'By this gift of a lamp on the thirteenth, may the son of the Sun (Yama) be pleased with me, together with Death, the noose and the staff, Time, and his consort Śyāmā.',[('mṛtyunā','with Death'),('pāśa-daṇḍābhyām','with the noose and the staff'),('kālena','with Time'),('śyāmayā saha','with Śyāmā'),('dīpa-dānāt','by the gift of a lamp'),('sūryajaḥ','the Sun-born, Yama')],'<b>A lamp for the god of death.</b> The Skanda Purāṇa (Kārttika-māhātmya 9.20–26) says the lamp is set out early in the night, outside the door, facing south, and that whoever does so need not fear untimely death. The Padma Purāṇa gives the same rite with a slightly different wording of this verse. Yama is not treated as an enemy here: he is invited to be <i>pleased</i>.',k='Yama is <b>honoured, not feared</b>.',note='Text as on shlokam.org (Yam Deep Dan Mantra), which follows the form chanted today; the Padma Purāṇa (Uttara Khaṇḍa) reads “mṛtyunā pāśahastena kālena bhāryayā saha / trayodaśīdīpadānāt…”. Traditions differ on the words.'),
 reading('niru','NĪRU TUMBUVA HABBA','Karnataka’s water-filling day',svg(560,170,'Decorated copper water pots being filled beside a wood-fired bath boiler',ground(560,170,130)+g(120,150,1.6,pot_deco())+g(220,150,1.6,pot_deco())+g(330,150,2,kalasha())+'<rect x="410" y="80" width="80" height="70" rx="8" fill="#8a5a3a"/>'+g(450,150,1,flames())+g(450,70,.9,lamp())),['<b>The water festival.</b> In much of Karnataka, Trayodaśī is <b>nīru tumbuva habba</b>, the festival of filling water. The big copper bath-boiler (<i>hande</i>) and the water pots are scrubbed, painted with lime and kuṅkuma, garlanded with flower strings and filled with fresh water for the next dawn’s oil bath. Many worship the filled vessel as Gaṅgā.','<b>Why the night before.</b> The water stands overnight in the decorated vessels, and the fire under the boiler is kept going so the bath is hot before sunrise. The Skanda Purāṇa says that at the Caturdaśī bath “Lakṣmī is in the oil and Gaṅgā in the water”: the vessel is being prepared for Gaṅgā.','<b>In the Malnāḍ and Uttara Kannaḍa.</b> Hill villages fetch the water from a river or well with song; some set up a new earthen pot as a household goddess of herbs and health, and fill it with leaves and medicinal plants. Customs vary from village to village.','<b>Across India.</b> The same evening the north buys gold, silver and new utensils for <b>Dhanteras</b>, farmers decorate their cattle, and Tamil homes prepare <i>marundu</i>, a medicinal paste eaten before the festival sweets.'],[('z','So Karnataka worships the bath water?'),('b','The water that will wash you on the holiest morning of the year, yes. Fill it with care, and the bath becomes a Gaṅgā-snāna at home.')],'Fill the pots <b>for tomorrow’s Gaṅgā</b>.'),
 story('naraka1','DAY 2 · THE DEMON OF PRĀGJYOTIṢA','Naraka Caturdaśī, part one',strip('Three panels: Indra complaining to Kṛṣṇa; Kṛṣṇa and Satyabhāmā flying on Garuḍa; the fortified city with fire, water and walls',[panel([(god('#e0a800'),0.91),(krishna(),0.98)],'#fff3cf',150),panel([(garuda(),.8),(krishna(),0.63),(person('#c0392b'),0.63)],'#dfe9f6',None),panel([(palace(),0.84),(flames(),0.84)],'#fde4e4',150)],['Indra’s complaint','on Garuḍa','the fortress']),'The fourteenth belongs to Kṛṣṇa. The story is told in the Bhāgavata Purāṇa, book 10, chapter 59.',['<b>Naraka</b>, also called Bhauma (“son of the Earth”), ruled Prāgjyotiṣa in the east. Later Purāṇas make him the son of Bhūmi, the Earth goddess, by Varāha.','Grown proud, he stole the earrings of <b>Aditi</b>, mother of the gods, and the royal umbrella of Varuṇa, seized a peak of Mount Mandara, and shut away sixteen thousand princesses in his palace.','Indra came to Dvārakā and told Kṛṣṇa. Kṛṣṇa mounted Garuḍa and, the Bhāgavata says, took his queen <b>Satyabhāmā</b> with him.','Prāgjyotiṣa was ringed by hills, by weapons that fired themselves, by water, fire and wind, and by the snare-wires of the demon Mura.','Kṛṣṇa broke the rock with his mace, the weapons with arrows, the fire, water and wind with his discus, the wires with his sword, and blew his conch till the city’s magic seals shattered.'],[('z','Why take Satyabhāmā to a war?'),('b','Traditions differ. The Bhāgavata simply says she came. Some tellings say she asked to; in others she is Bhūmi herself, and that matters in the next part.')],'Kṛṣṇa rides <b>against the thief of heaven</b>.'),
 story('naraka2','THE FALL OF NARAKA','Naraka Caturdaśī, part two',strip('Three panels: Kṛṣṇa’s discus cutting down the five-headed Mura; Naraka on an elephant struck by the discus; the Earth goddess returning the earrings and the princesses freed',[panel([(discus(),1.2),(demon('#2a3a5a'),0.98)],'#dfe9f6',150),panel([(elephant(False),0.77),(discus(),.9)],'#fde4e4',150),panel([(devi(sari='#2f7a3a',items=('abhaya',)),0.84),(person('#c0392b'),0.70),(person('#e0a800'),0.70)],'#fff3cf',150)],['Mura falls','Naraka falls','the Earth’s prayer']),'Bhāgavata 10.59, verses 6–37.',['The five-headed <b>Mura</b> rose from the moat and hurled his trident at Garuḍa. Kṛṣṇa split it with arrows and cut off his heads with the discus; that is why he is called <b>Murāri</b>, enemy of Mura. Mura’s seven sons fell after him.','Naraka came out on an elephant. His weapons failed against Garuḍa, and as he raised his trident, Kṛṣṇa’s discus severed his head.','<b>Bhūmi</b>, the Earth, came forward with Aditi’s earrings, Varuṇa’s umbrella and the Vaijayantī garland, praised Kṛṣṇa, and placed Naraka’s frightened son Bhagadatta at his feet. Kṛṣṇa gave the boy fearlessness.','In the palace Kṛṣṇa found the sixteen thousand captive princesses and sent them to Dvārakā with honour; he returned the earrings to Aditi in heaven.','Popular tradition adds two things the Bhāgavata does not: that Naraka could die only at his mother’s hand, so <b>Satyabhāmā</b>, an incarnation of Bhūmi, struck the blow; and that the dying Naraka asked that his day be kept with lamps and a bath.'],[('z','A demon asked for a festival?'),('b','So the story goes, Zappy. He saw his mistake at the end and asked to be remembered not with mourning but with light. That’s the generosity of the tradition.')],'Pride falls; <b>the captives go free</b>.'),
 reading('bath','THE DAWN OIL BATH','Abhyaṅga snāna and the Yama-tarpaṇa',svg(560,170,'A mother applying oil to a child’s head before dawn, with a steaming pot and a lamp',sky(560,170,'#3a3a6a')+ground(560,170,140)+g(200,150,1.2,mother())+g(270,150,1,child())+g(400,150,1.6,pot_deco())+'<path d="M392 92 q6 -10 0 -20 M408 92 q6 -10 0 -20" fill="none" stroke="#fff" stroke-width="2"/>'+g(480,150,1.2,lamp())),['<b>Before sunrise.</b> The Skanda Purāṇa tells everyone to bathe on Caturdaśī before dawn, while the stars are still out, after rubbing the body with sesame oil: “<b>Lakṣmī is in the oil and Gaṅgā in the water</b>,” and whoever bathes so “does not see Yama’s world.” Hence the Tamil greeting “<i>Gaṅgā snānam āccā?</i>”, have you had your Gaṅgā bath?','<b>At home in Karnataka.</b> The eldest woman applies warm oil to everyone’s head, the children first; a paste of gram flour or herbs follows, then the hot water from the pots filled the night before. Then new clothes, the first sweets, the first crackers, and the elders’ blessings.','<b>The apāmārga.</b> During the bath a sprig of the thorny <b>apāmārga</b> (prickly chaff-flower), with a clod of earth from a furrow, is turned around the head three times while a verse is said (next page): the sin is “turned away”.','<b>Yama-tarpaṇa and lamps.</b> The same text has bathers offer water with sesame to Yama under fourteen names (Yama, Dharmarāja, Mṛtyu, Antaka, Vaivasvata, Kāla…) and, in the evening, a <b>four-wicked lamp</b> to Naraka himself; many also light a lamp for Yama’s two dogs. In parts of the north the day is Choṭī Dīvālī or Rūp Caudas.'],[('z','Oil before a bath? Doesn’t that defeat the point?'),('b','Ask any grandmother, Zappy. The oil soaks in, the hot water opens the skin, and you come out softer than ever. The scripture calls it Lakṣmī and Gaṅgā; your skin calls it winter care.')],'Oil is Lakṣmī, <b>water is Gaṅgā</b>.'),
 verse('v-apamarga','The apāmārga verse','Turned round the head during the Caturdaśī bath',['sītāloṣṭasamāyukta sakaṇṭakadalānvita','hara pāpam apāmārga bhrāmyamāṇaḥ punaḥ punaḥ'],svg(200,150,'A thorny apāmārga sprig being turned in a circle above a head',ground(200,150,125)+g(100,140,1,child())+g(100,60,1.2,apamarga())+'<ellipse cx="100" cy="40" rx="40" ry="10" fill="none" stroke="#2f7a3a" stroke-width="2" stroke-dasharray="4 4"/>'),'O apāmārga, joined with a clod from the ploughed furrow, with your thorns and leaves: turned round again and again, take away my sin.',[('sītā-loṣṭa','a clod of earth from the furrow'),('sa-kaṇṭaka-dala','with thorny leaves'),('hara','take away'),('pāpam','sin'),('bhrāmyamāṇaḥ','being turned round'),('punaḥ punaḥ','again and again')],'<b>The plant that “wipes away”.</b> <i>Apāmārga</i> is read as “that which wipes off” (apa + mṛj), and the Skanda Purāṇa (Kārttika-māhātmya 9.33–35) prescribes it to “destroy Naraka”, here both the demon and hell (<i>naraka</i>). The clod of furrow-earth ties the rite to the farm: a harvest-season bath. Many families now skip the sprig but keep the verse.',k='What is <b>turned away</b> is the sin.',note='Text as on shlokam.org (Abhyang Snan Mantra). The Naraka lamp verse used in the evening, “datto dīpaś caturdaśyāṃ narakaprītaye mayā…”, comes from later pūjā manuals; the Padma Purāṇa only prescribes the lamp.'),
 reading('night','DAY 3 · THE NIGHT OF LAKṢMĪ','Amāvāsyā in the Skanda Purāṇa',svg(560,180,'A decorated home at night with lamps on every step and window and Lakṣmī on a lotus within',nightsky(560,180)+'<path d="M140 170 v-90 l140 -50 l140 50 v90z" fill="#c98a5a"/>'+g(280,165,1,lakshmi())+lamps_row(6,160,52,176,1.1)+''.join(g(x,y,.9,lamp()) for x,y in [(170,100),(390,100),(210,70),(350,70)])),['<b>The day.</b> The Skanda Purāṇa’s programme for the new moon is precise. In the morning, a bath and a <b>pārvaṇa śrāddha</b> for the ancestors: Dīpāvali begins with the dead. In the evening, Lakṣmī is worshipped in a decorated pavilion, a bed is made for her, and sweets (<i>laḍḍukas</i>) are offered.','<b>Torches for the ancestors.</b> In the early night lamps and firebrands (<i>ulkā</i>) are lifted to show the ancestors their way back after the fortnight of '+L('/festivals/pitru-paksha/','Pitṛ Pakṣa')+'. Much later, firecrackers took over this place; the text speaks only of lamps and torches.','<b>Driving out Alakṣmī.</b> At midnight, the text says, the town goes round with music, and before dawn the women of the house drive out <b>Alakṣmī</b>, misfortune, Lakṣmī’s sister, with the noise of winnowing fans and drums. Then Lakṣmī is woken and the house is hers.','<b>The night of waking.</b> The night is called <b>Sukharātri</b>, the happy night, and the text asks people to stay awake, with the Purāṇa, songs, dice or the '+L('/vishnu/bhagavad-gita/','Gītā')+'. Lakṣmī, says the old belief, goes looking for homes that are awake, clean and lit.'],[('z','Ancestors and Lakṣmī on the same day?'),('b','Gratitude to those who came before, then welcome to what comes next. The text does both, morning and night.')],'Clean, lit, <b>and awake</b>.'),
 story('lakshmi','LAKṢMĪ CHOOSES','Why she comes on this night',strip('Three panels: Lakṣmī rising from the ocean on a lotus; Lakṣmī garlanding Viṣṇu; Bali asking Viṣṇu that Lakṣmī stay in lit homes',[panel([(river(144,140),1),(lakshmi(),0.91)],'#dfe9f6',None),panel([(lakshmi(),0.84),(vishnu(),0.84)],'#fff3cf',150),panel([(bali(),0.84),(vishnu(),0.77),(lamp(),1)],'#20243a',150)],['Śrī rises','she chooses Viṣṇu','Bali’s wish']),'Two stories explain the Lakṣmī Pūjā.',['From the churned ocean rose <b>Śrī</b>, Lakṣmī, on a lotus, so beautiful that gods, demons and sages all wanted her (Bhāgavata 8.8).','She looked over them all, the proud, the angry, the ascetic, the unkind, and found every one wanting. At last she placed her garland on <b>Viṣṇu</b>, who wanted nothing, and made his chest her home.','Popular tradition holds that this choosing, or her marriage to Viṣṇu, fell on the Dīpāvali new moon.','The Skanda Purāṇa adds another story: when Vāmana granted Bali a boon, Bali asked that <b>Lakṣmī stay permanently</b> in every house that lights lamps on these days of his rule.','So Lakṣmī is worshipped on the darkest night in homes made clean and bright, with the ledgers, the coins, the jewellery, and the lamp itself.'],[('z','She chose the one who didn’t want her?'),('b','Wealth stays with those who don’t grab, Zappy. That’s the oldest lesson of Lakṣmī.')],'Śrī stays <b>where there is light</b>.'),
 verse('v-dipa','Śubhaṃ karoti','The lamp verse said at dusk',['śubhaṃ karoti kalyāṇam ārogyaṃ dhanasaṃpadā','śatrubuddhivināśāya dīpajyotir namo’stu te'],svg(200,150,'A single lamp before Lakṣmī with coins and a lotus',ground(200,150,120,'#e3eaf3')+g(60,130,1,lotus())+g(100,128,2.4,lamp())+g(150,130,1,coins())),'O light of the lamp, you bring what is good and auspicious, health and wealth; to destroy the thought of enmity, salutations to you.',[('śubham','the auspicious'),('kalyāṇam','well-being'),('ārogyam','health'),('dhana-saṃpadā','wealth and plenty'),('śatru-buddhi','hostile thought'),('dīpa-jyotiḥ','the lamp’s flame')],'<b>The lamp worshipped as Lakṣmī.</b> This is the verse many Karnataka and Maharashtra homes say every evening when the lamp is lit, and it is said with special care on the Dīpāvali night. Note what it asks the light to destroy: not enemies but <i>the thought of enmity</i>. Families add a Lakṣmī hymn such as the '+L('/devi/mahalakshmi-ashtakam/','Mahālakṣmyaṣṭakam')+' or '+L('/devi/kanakadhara-stotram/','Kanakadhārā Stotram')+'.',k='Light for <b>health, wealth and peace</b>.',note='Text as on shlokam.org (Lighting the lamp). A traditional household verse; we have not traced it to a single text. Some read “dhanasaṃpadaḥ”.'),
 cards('elsewhere','THE SAME NIGHT ELSEWHERE','Kālī, Kedāra Gaurī and the new ledgers',fig_row('Kālī, a red ledger, a Gaurī kalaśa and a Jain lamp',[(devi(skin='#2a2a3a',sari='#c0392b',items=('sword','abhaya')),.6),(ledger(),1.3),(kalasha(),1.3),(lamp(),1.6)],['Kālī','the ledger','Kedāra Gaurī','Mahāvīra’s lamp'],gy=150),[('🌑','Bengal and Assam','The night is <b>Kālī Pūjā</b>. Records show Lakṣmī was worshipped here earlier; the great Kālī celebrations grew mainly from the twentieth century. Related reading: '+L('/devi/dasha-mahavidya/','the Mahāvidyās')+'.'),('📒','Traders','Shops worship their account books with “śubha lābha” written in them; in Gujarat new ledgers open (cōpḍā pūjan), and the next day is the new year.'),('🏺','Karnataka','Many families keep the <b>Kedāra Gaurī vrata</b> on Amāvāsyā, worshipping Pārvatī as Kedāra Gaurī with a kalaśa and a twenty-one-knot thread; farming homes add Gaurī and cow worship.'),('🪔','Jains and Sikhs','Jains keep the night as <b>Mahāvīra’s nirvāṇa</b>: when his light went out, the story says, eighteen kings lit lamps. Sikhs keep <b>Bandī Choṛ Divas</b> for Guru Hargobind’s release from Gwalior fort. Newar Buddhists keep the five days as Swanti.')],[('z','So the same lamps mean different things?'),('b','The same lamp, many prayers. That’s why Dīpāvali belongs to everyone.')],'One night, <b>many prayers</b>.'),
 story('bali','DAY 4 · THREE STEPS OF LAND','Bali and Vāmana',strip('Three panels: Bali at his sacrifice greeting a dwarf boy with an umbrella; the boy growing into a giant whose step covers the sky; Bali bowing his head for the third step',[panel([(bali(),0.84),(vamana(),1)],'#fff3cf',150),panel([(big_step(),1),(sun(14),.8)],'#dfe9f6',150),panel([(bali(),0.77),(big_step(),0.70)],'#e9e3f5',150)],['the little brahmin','the giant steps','Bali’s head']),'The story is in the Bhāgavata Purāṇa, book 8, chapters 15–23. Read also our '+L('/vishnu/dashavatara/vamana/','Vāmana article')+'.',['<b>Bali</b>, grandson of Prahlāda, was a just and generous asura king who had conquered the three worlds and driven Indra from heaven. Viṣṇu would not kill a good king and a devotee.','Instead he was born as <b>Vāmana</b>, a dwarf brahmin boy with an umbrella, and came to Bali’s great sacrifice, where the king had promised to give anything asked.','Vāmana asked only for <b>three steps of land</b>. Bali’s guru Śukra warned him it was Viṣṇu himself; Bali replied that he would not break his word, and poured the water of the gift.','The boy grew into <b>Trivikrama</b>: one step covered the earth, a second the heavens. Nothing was left for the third. Bali bowed and offered his own head.','Pleased, Viṣṇu sent him to rule <b>Sutala</b> below the earth, promised he would be Indra in a future age, and stood guard at his door himself. Popular tradition adds the boon of Bali Pratipadā: once a year Bali may come home.'],[('z','So Bali lost?'),('b','He lost a kingdom and kept his word. The Bhāgavata treats that as the greater victory, and so does every Karnataka village that welcomes him.')],'He gave even <b>his own head</b>.'),
 verse('v-bali','Bhāgavata 8.22.2','Bali offers his head for the third step',['yady uttamaśloka bhavān mameritaṃ','vaco vyalīkaṃ suravarya manyate','karomy ṛtaṃ tan na bhavet pralambhanaṃ','padaṃ tṛtīyaṃ kuru śīrṣṇi me nijam'],svg(200,150,'Bali bowing while a great foot descends on his head',ground(200,150,128,'#e9e3f5')+g(90,140,.9,bali())+g(70,20,.9,big_step(),rot=150)),'O Lord of highest renown, O best of the gods: if you think the word I promised has turned false, I shall make it true; let it not be a deceit. Place your third step on my head.',[('uttamaśloka','O Lord of highest fame'),('vyalīkam','false'),('ṛtam','true'),('pralambhanam','deceit'),('padaṃ tṛtīyam','the third step'),('śīrṣṇi me','on my head')],'<b>The king who kept his word.</b> Bali’s answer is the heart of Day 4. He has lost everything he owned, his guru has cursed him for giving, and still his one concern is that his promise not be false. That is why the Dharmasindhu counts Bali Pratipadā among the three most auspicious days of the year, and why Bali is <i>worshipped</i>, not defeated, on it.',k='A promise is worth <b>more than a kingdom</b>.',note='Text: Bhāgavata Purāṇa 8.22.2, as in the BBT edition (prabhupadabooks.com), set in IAST.'),
 reading('padyami','BALI PĀḌYAMI IN KARNATAKA','Balīndra comes home',svg(560,170,'A triangular cow-dung figure of Bali decorated with marigolds on a plank, with a lamp, and a decorated cow beside it',ground(560,170,135)+'<rect x="150" y="130" width="140" height="14" fill="#8a5a3a"/>'+g(220,130,1.6,balifig())+g(320,134,1.2,lamp())+g(450,150,1.1,cow())),['<b>The welcome.</b> On Kārtika Śukla Pratipadā, Karnataka welcomes <b>Bali Cakravarti</b>, often called <b>Balīndra</b>. In many villages a figure of Bali, often a triangle of cow dung, is shaped on a plank set on a rangoli, crowned with marigolds and worshipped with lamps; Bali and his queen Vindhyāvali are honoured together.','<b>Coastal Karnataka.</b> In Tuḷunāḍu Dīpāvali is above all Bali’s festival: lamps are set on the paddy fields and cattle sheds, and Bali is called back with the cry for “Balīndra” to come and see how well his people live. Read more in our '+L('/tulunadu/festivals/','Tuḷunāḍu festivals')+'.','<b>Gō-pūjā.</b> Cows and bullocks are bathed, their horns painted, garlanded and fed sweets, and the cowshed is worshipped. The Skanda Purāṇa’s chapter opens with a cow-and-calf vow (Vatsa Dvādaśī), and the cattle remain at the centre of Day 4 in farming homes.','<b>Elsewhere.</b> In the north the day is <b>Govardhana Pūjā</b>: a hill of cow dung or a mountain of food (<b>Annakūṭa</b>) is offered to Kṛṣṇa, who lifted Govardhana. Maharashtra calls it Pāḍvā; Gujarat keeps its new year; Kerala welcomes the same Mahābali at Ōṇam. Many families play dice, recalling the story that Śiva and Pārvatī played on this day and Pārvatī won.'],[('z','Why cow dung for a king?'),('b','Because it is what the farm has, Zappy: clean, sacred and made by the cow. Bali was a king of farmers. They make him from the earth they live on.')],'The good king <b>comes home</b>.'),
 story('yama','DAY 5 · YAMA DINES WITH HIS SISTER','Yama Dvitīyā',strip('Three panels: Yamunā inviting her brother; Yama arriving on his buffalo; Yamunā feeding him and marking his forehead',[panel([(person('#2a5aa8'),1.05),(river(144,150),1)],'#dfe9f6',None),panel([(buffalo(),0.77),(yama(),0.77)],'#e9e3f5',150),panel([(person('#2a5aa8'),0.84),(plate(),1),(yama(),0.84)],'#fff3cf',150)],['the sister waits','Yama arrives','the meal and the tilaka']),'The last day is for brothers and sisters.',['<b>Yama</b>, lord of death, and <b>Yamunā</b>, the river, are twins, children of the Sun. Yamunā asked her brother again and again to visit her, and he never found the time.','On the second day of Kārtika’s bright fortnight he came at last. Yamunā bathed him, marked his forehead with tilaka, garlanded him and fed him with her own hands.','Delighted, Yama offered her a boon. She asked that any brother who visits his sister on this day and eats from her hand should be free from the fear of untimely death.','Yama granted it. So the day is <b>Yama Dvitīyā</b>, also <b>Bhaginī-hasta-bhojana</b>, “eating from the sister’s hand”. Many bathe in the Yamunā this day.','Another telling says that after killing Naraka, Kṛṣṇa visited his sister <b>Subhadrā</b>, who welcomed him with sweets, lamps and a tilaka.'],[('z','The festival starts with a lamp for Yama and ends with Yama at dinner?'),('b','Exactly, Zappy. It begins with keeping death at the door and ends with feeding him at the table. Dīpāvali makes even death family.')],'Brothers fed, <b>death made gentle</b>.'),
 cards('siblings','HOW YAMA DVITĪYĀ IS KEPT','Bhāī Dūj and its cousins',fig_row('A sister doing ārati for her brother, a plate of sweets and a tilaka',[(person('#c0392b'),1),(arati(),1.4),(person('#2a5aa8'),1),(plate(),1.4)],['sister','ārati','brother','the meal'],gy=150),[('🍛','The meal','Brothers go to their sisters’ homes and eat a meal she cooks; she does ārati, applies a tilaka and prays for his long life; he gives a gift in return.'),('🗺️','The names','Bhāī Dūj in the north, Bhāū Bīj in Maharashtra and Goa, Bhāī Phõṭā in Bengal, Bhāī Ṭīkā in Nepal (with a seven-coloured mark), Bhaginī Hasta Bhojanamu in Andhra and Telaṅgāṇa, Yama Dvitīyā in Karnataka homes.'),('🪔','In Karnataka','Kept by many families rather than everywhere; in some areas the sisters’ ārati is done on the water-filling day or on Pāḍyami instead. Practice follows the family.'),('🌙','No brother?','In Maharashtra a woman without a brother may worship the moon as her brother; in many homes a cousin or a brother-in-spirit is fed.')],[('z','Like Rakṣā Bandhan?'),('b','Cousins, Zappy. In '+L('/festivals/shravana-purnima/raksha-bandhan/','Rakṣā Bandhan')+' the sister ties a thread; here she feeds him. Both say: I want you to live long.')],'A sister’s meal for <b>a brother’s long life</b>.'),
 reading('rama','RĀMA COMES HOME','Dīpāvali in the north',svg(560,170,'A city gate lit with lamps welcoming a figure with a bow, a woman and a younger brother returning',nightsky(560,170)+g(280,160,1.1,palace())+lamps_row(9,40,60,166,1.1)+g(150,160,.7,god('#2a5aa8'))+g(185,160,.6,person('#c0392b'))+g(115,160,.6,god('#e0a800'))+g(140,100,.6,bow())),['<b>The return.</b> Across north India Dīpāvali is above all Rāma’s homecoming: after fourteen years of exile and the defeat of Rāvaṇa, Rāma returned to Ayodhyā with Sītā and Lakṣmaṇa, and the city lit rows of lamps to welcome him. Read the life in our '+L('/vishnu/dashavatara/rama/','Rāma article')+'.','<b>What the texts say.</b> The Vālmīki Rāmāyaṇa describes Ayodhyā decorated with banners and flowers for the return and the coronation. The link between the return and the new-moon lamps is a beloved later tradition, strongest in the north; Karnataka families more often tell the Naraka and Bali stories.','<b>Twenty days apart.</b> Dasarā (Vijayadaśamī) marks Rāma’s victory, and Dīpāvali, about twenty days later, his arrival home; the tradition counts the journey back in between. (Popular tradition.)','<b>Ayodhyā today.</b> The ghāṭs of the Sarayū are lit with lakhs of lamps in a great Dīpotsava. The custom of lighting homes for a returning king, though, is what every household repeats.'],[('z','So which story is the real Dīpāvali?'),('b','All of them, Zappy. Naraka in the south, Rāma in the north, Bali in Karnataka, Mahāvīra for the Jains. The lamps don’t argue.')],'A city <b>lit for its king</b>.'),
 cards('home','A KARNATAKA DĪPĀVALI AT HOME','Lanterns, lamps and the sweets of the season',fig_row('A sky lantern, clay lamps, a rangoli and a plate of sweets',[(lantern(),1.4),(lamp(),1.8),(rangoli(),.9),(laddu(),1.8)],['ākāśa buṭṭi','haṇate','rangoli','sweets'],gy=150),[('🏮','Ākāśa buṭṭi','Star-shaped sky lanterns of paper and bamboo hung over the door, often from Naraka Caturdaśī right through Kārtika.'),('🪔','Haṇate','Clay lamps (<i>haṇate</i>) along walls, steps, windows, the tulasī platform and the well; many homes then light a lamp every evening of '+L('/festivals/kartika/','Kārtika')+'.'),('🍬','The kitchen','Hōḷige (obbaṭṭu), karjikāyi, cakkuli, kōḍubaḷe, adhirasa, kajjāya and the festival oṭṭu-śāvige; in the Malnāḍ, special dishes for each day.'),('🎶','The villages','In north Karnataka the festival is the <b>Haṭṭi habba</b>, the cattle-shed festival; in the Malnāḍ teams go house to house singing <b>antige-pintige</b> songs with a lamp, blessing each home.')],[('z','Antige-pintige?'),('b','Singers carrying a lamp from house to house, Zappy, who light your lamp from theirs and bless you with a song. The festival walks door to door.')],'Light passed <b>from house to house</b>.'),
 reading('meaning','WHAT DĪPĀVALI MEANS','Tamaso mā jyotir gamaya',svg(560,160,'A single lamp lighting another, and a dark room filling with light',nightsky(560,160)+g(200,120,2.4,lamp())+g(330,120,2.4,lamp())+'<path d="M230 96 q50 -30 74 0" fill="none" stroke="#ffd60a" stroke-width="3" stroke-dasharray="5 4"/>'+'<circle cx="265" cy="100" r="120" fill="#ffd60a" opacity=".08" stroke="none"/>'),['<b>Lead me from darkness to light.</b> The Bṛhadāraṇyaka Upaniṣad’s prayer, <i>tamaso mā jyotir gamaya</i> (1.3.28), is the line most teachers give as Dīpāvali’s meaning: the outer lamp stands for the inner light of knowledge. (Interpretation.)','<b>Every story is a victory of light.</b> Dhanvantari brings life; the bride’s lamps turn Yama back; Naraka’s captives go free; Lakṣmī chooses the one who does not grab; Bali gives even himself; Yamunā feeds her brother. Read in order, the five days move from fear of death to a feast with death at the table. (Our reading.)','<b>Cleaning as worship.</b> The house is whitewashed, swept and lit because Lakṣmī is said to enter only clean, bright, awake homes. Many read the outer cleaning as a picture of the inner one.','<b>Light without harm.</b> The texts speak of lamps and torches, not bangs. Many families now keep crackers few and outdoors for the sake of the air, the elderly and the animals; the oil lamp remains the heart of the festival.'],[('z','If I could do only one thing for Dīpāvali?'),('b','Light one lamp on the new-moon night, say the lamp verse, and give someone a sweet. The rest grows from there.')],'One lamp <b>lights another</b>.'),
 end(i,['<b>Day 1.</b> Dhanvantari and the Yama-dīpa; in Karnataka, the water pots are filled.','<b>Day 2.</b> Kṛṣṇa slays Naraka; the dawn oil bath, “Lakṣmī in the oil, Gaṅgā in the water”.','<b>Day 3.</b> Lakṣmī on the moonless night: ancestors, lamps, waking, and Alakṣmī driven out.','<b>Day 4.</b> Bali, who gave his head for a promise, comes home; cows worshipped.','<b>Day 5.</b> Yama eats from his sister’s hand; brothers visit sisters.'],'Read next: '+L('/festivals/kartika/','Kārtika Māsa, the month of lamps')+', which Dīpāvali begins, and then '+L('/subramanya/shashthi/','Subrahmaṇya Ṣaṣṭhī')+'.','Dīpāvali: five days of light'),
 sources([('Ritual programme:','Skanda Purāṇa, Vaiṣṇava Khaṇḍa, Kārttikamāsa-māhātmya, ch. 9 (G. V. Tagare trans., via wisdomlib.org): Vatsa Dvādaśī, Yama-trayodaśī and the lamp (vv. 17–26), Naraka-caturdaśī bath, apāmārga and Yama-tarpaṇa (vv. 27–49), Bali’s boon (vv. 49–60), Dīpāvali night, Lakṣmī, ulkā, Alakṣmī, Sukharātri (vv. 61–103). Padma Purāṇa, Uttara Khaṇḍa (Yama-dīpa, Naraka lamp).'),('Stories:','Bhāgavata Purāṇa 8.8 (churning, Lakṣmī, Dhanvantari, 8.8.34), 8.15–23 (Bali and Vāmana, 8.22.2), 10.59 (Naraka). Verse texts: BBT edition (vedabase, prabhupadabooks.com); shlokam.org for the Yama-dīpa, apāmārga, Naraka-lamp and lamp verses.'),('History and customs:','Wikipedia, “Diwali”, “Dhanteras”, “Balipratipada”, “Narakasura”, “Bhai Dooj” (early records, inscriptions, regional customs); Karnataka customs (nīru tumbuva habba, Bali figures, Malnāḍ and Tuḷunāḍu) from regional press and community sources, cross-checked against each other.')],'the Hima/Hemanaka story (only named in the Skanda Purāṇa; details are the popular telling); Satyabhāmā killing Naraka and Naraka’s request for lamps (popular, not in the Bhāgavata); Lakṣmī’s marriage on this night; Rāma’s return as the origin of the lamps; the Yama-Yamunā story (popular telling; we have not located the Purāṇic passage); Karnataka village customs (vary by district and family); the exact wording of inscriptions (from secondary summaries).','Verses in IAST from the named editions; numbering as in those editions.')]
build(i,'FIVE DAYS · NARAKA, LAKṢMĪ, BALI · AND YAMA',COV,'A row of lamps on the darkest night','The festival <b>day by day</b>, from the water pots of Trayodaśī to Yama’s dinner with his sister, with <b>every story</b> told in full, the <b>verses</b> of each day, and how <b>Karnataka</b> keeps it.','Dīpāvali explained day by day: Dhanvantari and the Yama-dīpa, Karnataka’s nīru tumbuva habba, Naraka Caturdaśī and the dawn oil bath, Lakṣmī Pūjā on the new moon, Bali Pāḍyami and Vāmana, Yama Dvitīyā, Rāma’s return, with the verses from the Skanda and Padma Purāṇas and the Bhāgavata.',pp)
print('deepavali ok', len(pp)+2,'pages')
